INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-001', 'De l''hort a casa', 'Recurs Pedagògic', 'STEAM', 'https://images.unsplash.com/photo-1592417817098-8f3d6910985b?auto=format&fit=crop&w=800&q=80', 'Maleta pedagògica sobre l''hort escolar i la sostenibilitat mediambiental per a Educació Primària i 1r cicle d''ESO.', '5 guies docents de camp, 8 kits de llavors ecològiques variades, 10 eines petites de jardineria infantil, quadern de camp plastificat, microscopi de camp portàtil.', 'https://drive.google.com/file/d/1DeLHortACasa_Dossier_CRP/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-002', 'Nanokit', 'Recurs Pedagògic', 'STEAM', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=800&q=80', 'Material experimental per introduir la nanociència, els nanomaterials i la tecnologia d''escala molecular a l''aula.', 'Superfícies superhidròfobes, mostres de filferro amb memòria de forma (nitinol), ferrofluid magnètic amb imants de neodimi, caixes Petri, 6 làmines explicatives.', 'https://drive.google.com/file/d/1Nanokit_Propostes_Didactiques/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-003', 'El diari de l''Arlet', 'Recurs Pedagògic', 'Impuls a la lectura', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?auto=format&fit=crop&w=800&q=80', 'Projecte interdisciplinari sobre la transició ecològica, canvi climàtic i energies renovables a través de la narrativa infantil.', '25 exemplars del conte El diari de l''Arlet, 4 plaques solars fotovoltaiques didàctiques amb motor i molinet, anemòmetre infantil, joc cooperatiu de taula.', 'https://drive.google.com/file/d/1Arlet_Guia_Energies_Renovables/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-004', 'Maleta Robòtica Bee-Bot & Blue-Bot', 'Recurs Pedagògic', 'STEAM', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?auto=format&fit=crop&w=800&q=80', 'Kit per treballar l''orientació espacial, la seqüenciació i el pensament computacional a Educació Infantil i Cicle Inicial.', '6 robots Bee-Bot recarregables, base d''estació de càrrega múltiple, 4 tapissos temàtics (Lletres, Ciutat, Geometria i Illa del Tresor), targetes de comandaments.', 'https://drive.google.com/file/d/1BeeBot_Activitats_Infantil_Primaria/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-005', 'Kit Makey Makey & Creació Interactiva', 'Recurs Pedagògic', 'STEAM', 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=800&q=80', 'Dispositiu per connectar objectes quotidians conductors amb programació Scratch per crear instruments, comandaments i experiments.', '8 plaques Makey Makey Classic amb cable USB, 48 cables de cocodril de colors, cablejats jumper, rotllos de cinta de coure conductora, dossier didàctic de reptes.', 'https://drive.google.com/file/d/1MakeyMakey_Reptes_Musica_Ciencia/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAT-006', 'Maleta Arqueologia i Evolució Humana', 'Recurs Pedagògic', 'STEAM', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=800&q=80', 'Rèpliques exactes de cranis d''homínids, fòssils i eines de sílex per a la investigació històrica i paleontològica a secundària.', '5 rèpliques de cranis (Australopithecus, H. habilis, H. erectus, Neanderthal, Sapiens), fòssils minerals, eines lítiques de pedra tallada, fitxes de datació i mesura.', 'https://drive.google.com/file/d/1Arqueologia_Hominitzacio_Guia/view?usp=sharing', 'Torns', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAQ-001', 'Impressora 3D Ender 3 Pro Didàctica', 'Maquinària i Equipament', 'Tècnic i audiovisual', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80', 'Equip complet d''impressió 3D FDM per a projectes tecnològics, disseny CAD amb Tinkercad i prototipatge escolar.', 'Impressora 3D muntada i calibrada, 1 bobina de filament PLA biodegradable (1 kg), alicates de tall, espàtula metàl·lica, targeta micro-SD amb adaptador USB i perfils de Cura.', 'https://drive.google.com/file/d/1Manual_Ender3_Seguretat_Escolar/view?usp=sharing', 'Setmanes', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAQ-002', 'Set Audiovisual: Croma i Il·luminació LED', 'Maquinària i Equipament', 'Tècnic i audiovisual', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?auto=format&fit=crop&w=800&q=80', 'Kit portàtil d''estudi de gravació per a telenotícies escolars, podcasts en vídeo i efectes especials de croma verd.', 'Fons verd desplegable autoportant de 2x1.5m, 2 focus LED bicolors amb trípodes regulables, micròfon sense fil corbater (USB-C/Lightning), bossa resistent de transport.', 'https://drive.google.com/file/d/1Croma_Guia_Edicio_Video_Escolar/view?usp=sharing', 'Setmanes', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAQ-003', 'Talladora i Plòter de Vinil Silhouette Cameo', 'Maquinària i Equipament', 'Tècnic i audiovisual', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=80', 'Màquina de tall de precisió per a vinil adhesiu, cartolines, vinil tèxtil per a samarretes i retolació de projectes del centre.', 'Plòter Silhouette Cameo 4, manta de tall adhesiva 30x30cm, ganiveta auto-ajustable, ganivet de pelat, cables d''alimentació i connexió USB, mostres de vinil.', 'https://drive.google.com/file/d/1Silhouette_Guia_Tall_Vinil/view?usp=sharing', 'Setmanes', 'Actiu');
INSERT INTO materials (id, nom, tipus, ambit, url_imatge, descripcio, contingut, url_guia, model_prestec, estat_general) VALUES ('MAQ-004', 'Kit 4 Ulleres Realitat Virtual Meta Quest', 'Maquinària i Equipament', 'Tècnic i audiovisual', 'https://images.unsplash.com/photo-1622979135225-d2ba269bc1df?auto=format&fit=crop&w=800&q=80', 'Equipament immersiu per a visites virtuals a museus, viatges espacials, anatomia humana i entorns 3D per a l''alumnat.', '4 visors VR autònoms amb corretges confort, 8 comandaments tàctils amb piles recarregables, carregador múltiple de 4 ports USB-C, maleta rígida antichoc.', 'https://drive.google.com/file/d/1VisorsVR_Guia_Us_Didactic_CRP/view?usp=sharing', 'Setmanes', 'Actiu');
